#include <iostream>
using std::cin;
using std::cout;
using std::cerr;
using std::endl;
#include <vector>
using std::vector;
using std::pair;
#include <map>
using std::map;
#include <array>
using std::array;

using std::max;
using std::min;
using std::swap;

#ifdef DEBUG
const int debug = 1;
#else
const int debug = 0;
#endif

using ll = int64_t;
using P = pair<ll, ll>;

ll n, q;
vector<ll> a;



void solve () {
	vector<ll> pq[2];
	pq[0] = a;
	pq[1].resize(n);
	for (ll i = 0; i < n; i++) {
		pq[1][a[i]] = i;
	}
	ll pi = 0;

	for (ll qi = 0; qi < q; qi++) {
		ll qt;
		cin >> qt;
		if (qt == 1) {
			ll x, y;
			cin >> x >> y;
			--x;
			--y;

			// type 1 (swap)
			ll px = pq[pi][x];
			ll py = pq[pi][y];
			swap(pq[pi  ][x ], pq[pi  ][y ]);
			swap(pq[pi^1][px], pq[pi^1][py]);

		} else {
			// type 2 (inverse)
			pi ^= 1;

		}
	}

	for (ll i = 0; i < n; i++) {
		if (i > 0) { cout << " "; }
		cout << (pq[pi][i] + 1);
	}
	cout << "\n";
	return;
}

int main (void) {
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);

	cin >> n >> q;
	a.resize(n);
	for (ll i = 0; i < n; i++) {
		cin >> a[i];
		a[i]--;
	}

	solve();

	return 0;
}
